using FamilyVeda.Domain.Records;

namespace FamilyVeda.UnitTests;

public sealed class LabRangeClassifierTests
{
    [Theory]
    [InlineData(11.9, LabRangeStatus.BelowRange)]
    [InlineData(12.0, LabRangeStatus.WithinRange)]
    [InlineData(15.0, LabRangeStatus.WithinRange)]
    [InlineData(15.1, LabRangeStatus.AboveRange)]
    public void Classify_UsesInclusivePrintedBounds(decimal value, LabRangeStatus expected)
    {
        Assert.Equal(expected, LabRangeClassifier.Classify(value, 12.0m, 15.0m));
    }

    [Theory]
    [InlineData(null, 15.0)]
    [InlineData(12.0, null)]
    [InlineData(null, null)]
    [InlineData(16.0, 15.0)]
    public void Classify_WhenRangeMissingOrInvalid_ReturnsUnavailable(double? low, double? high)
    {
        var result = LabRangeClassifier.Classify(13m, (decimal?)low, (decimal?)high);

        Assert.Equal(LabRangeStatus.RangeUnavailable, result);
    }
}
